package dev.redstoneengineering.physics;
import dev.redstoneengineering.block.*;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import java.util.*;
/** Discrete pressure-wave propagation through configured fluid-filled tubes. */
public final class HydroacousticNetwork{private HydroacousticNetwork(){}private record N(BlockPos p,int a){}public static void propagate(ServerLevel l,BlockPos src,int amp,int freq){ArrayDeque<N>q=new ArrayDeque<>();Map<BlockPos,Integer>best=new HashMap<>();for(Direction d:Direction.values())q.add(new N(src.relative(d),amp));int count=0;while(!q.isEmpty()&&count<NetworkKernel.MAX_NODES){N n=q.removeFirst();if(n.a<=0||!l.hasChunkAt(n.p))continue;if(best.getOrDefault(n.p,-1)>=n.a)continue;best.put(n.p,n.a);count++;var s=l.getBlockState(n.p);var b=s.getBlock();if(b instanceof HydroacousticReceiverBlock){InformationRuntime.write(l,"hydro",n.p,n.a,freq,true,100);l.scheduleTick(n.p,b,1);continue;}if(!(b instanceof HydroacousticTubeBlock))continue;int medium=s.getValue(HydroacousticTubeBlock.MEDIUM);int loss=medium==0?1:medium==1?2:3;int next=n.a-loss;for(Direction d:Direction.values())q.add(new N(n.p.relative(d),next));}NetworkKernel.recordScan(l,"hydro",count,count>=NetworkKernel.MAX_NODES);}}
